    override fun getMetricsStream(): Flow<List<PerformanceMetricEntity>> = 
        dao.getMetricsStream().flowOn(Dispatchers.IO)

    override suspend fun insertMetric(metric: PerformanceMetricEntity) {
        withContext(Dispatchers.IO) {
            try {
                dao.insertMetric(metric)
            } catch (e: Exception) {
                // Production logging: Integrate Crashlytics/Timber here
                Log.e("DataLayer", "Failed to insert metric: ${e.message}")
            }
        }
    }
}
